import fitz, numpy as np
d = fitz.open('eprint/figures/exclusions.pdf')
p = d[0]
draws = p.get_drawings()

def path_pts(dr):
    pts = []
    for it in dr['items']:
        if it[0] == 'l':
            if not pts: pts.append((it[1].x, it[1].y))
            pts.append((it[2].x, it[2].y))
        elif it[0] == 'c':
            if not pts: pts.append((it[1].x, it[1].y))
            pts.append((it[4].x, it[4].y))
    return np.array(pts)

pts = path_pts(draws[217])  # IRAS equilibrium solid
mu = 10**(-20 + (pts[:,0]-69.29)/53.933)
f  = 10**(-19 + (167.55-pts[:,1])/20.266)
print("n =", len(mu))
print("path start:", mu[0], f[0], " end:", mu[-1], f[-1])
# print every 4th point to see shape
for i in range(0, len(mu), 6):
    print(f"{i:3d}  mu={mu[i]:.4e}  finv={f[i]:.4e}")
print(f"{len(mu)-1:3d}  mu={mu[-1]:.4e}  finv={f[-1]:.4e}")
np.savetxt('iras_eq_contour.txt', np.column_stack([mu, f]))
